#!/usr/bin/env node
// Generates the SDK from the host's own sources, so the three can't drift (design/plugin-v2 01 §5, 06 §1):
//   runtime/boot.js, runtime/globals.js, runtime/astra.js  ← src/Astra.Plugins/V2/Runtime (the exact code plugins run against)
//   src/components.g.d.ts              ← src/Astra.Plugins/V2/Ui/components.json (the UI 1.0 schema)
// --check fails when a generated file is stale (CI).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../../..');
const pkg = path.resolve(here, '..');
const check = process.argv.includes('--check');
const v2 = path.join(root, 'src/Astra.Plugins/V2');

const outputs = new Map();
outputs.set(path.join(pkg, 'runtime/boot.js'), fs.readFileSync(path.join(v2, 'Runtime/boot.js'), 'utf8'));
outputs.set(path.join(pkg, 'runtime/globals.js'), fs.readFileSync(path.join(v2, 'Runtime/globals.js'), 'utf8'));
outputs.set(path.join(pkg, 'runtime/astra.js'), fs.readFileSync(path.join(v2, 'Runtime/astra.js'), 'utf8'));

const schemaText = fs.readFileSync(path.join(v2, 'Ui/components.json'), 'utf8');
const schema = JSON.parse(schemaText);
outputs.set(path.join(pkg, 'runtime/components.json'), schemaText);
const tsType = (kind) => {
  if (kind === 'string' || kind === 'text') return 'string';
  if (kind === 'number') return 'number';
  if (kind === 'boolean') return 'boolean';
  if (kind === 'node') return 'UiNode';
  if (kind === 'nodes') return 'UiNode[]';
  if (kind === 'action') return 'UiAction';
  if (kind.startsWith('enum:')) return kind.slice(5).split('|').map((v) => JSON.stringify(v)).join(' | ');
  if (kind.startsWith('token:')) {
    const t = kind.slice(6);
    if (t === 'icon') return 'string';
    if (t === 'width') return `${schema.tokens.width.map((v) => JSON.stringify(v)).join(' | ')} | number | Responsive<${schema.tokens.width.map((v) => JSON.stringify(v)).join(' | ')} | number>`;
    if (t === 'gap') return `Gap | Responsive<Gap>`;
    return schema.tokens[t].map((v) => JSON.stringify(v)).join(' | ');
  }
  return 'unknown';
};
const lines = [
  '// Generated by packages/plugin-sdk/scripts/gen.mjs from src/Astra.Plugins/V2/Ui/components.json — do not edit.',
  `// UI protocol ${schema.version}`,
  "import type { UiAction, UiNode, Responsive, Condition } from './index';",
  `export type Gap = ${schema.tokens.gap.map((v) => JSON.stringify(v)).join(' | ')};`,
  `export type Tone = ${schema.tokens.tone.map((v) => JSON.stringify(v)).join(' | ')};`,
  `export type Format = ${schema.tokens.format.map((v) => JSON.stringify(v)).join(' | ')};`,
  '',
  '/** Props every component takes. */',
  'export interface CommonProps {',
  '  key?: string;',
  '  visible?: boolean | Condition;',
  '  disabled?: boolean | Condition;',
  ...Object.entries(schema.common).filter(([k]) => !['visible', 'disabled'].includes(k)).map(([k, v]) => `  ${k}?: ${tsType(v)};`),
  '}',
  '',
  '/** Props every input takes (its value lives in the shell\'s local state bag under name). */',
  'export interface InputProps {',
  ...Object.entries(schema.inputProps).map(([k, v]) => `  ${k}?: ${tsType(v)};`),
  '}',
  '',
];
for (const [name, def] of Object.entries(schema.components)) {
  lines.push(`export interface ${name}Props extends CommonProps${def.input ? ', InputProps' : ''} {`);
  for (const [k, v] of Object.entries(def.props)) lines.push(`  ${k}${(def.required ?? []).includes(k) ? '' : '?'}: ${tsType(v)};`);
  for (const r of def.required ?? []) if (!(r in def.props)) lines.push(`  ${r}: ${tsType(schema.common[r] ?? 'string')};`);
  lines.push('}');
}
lines.push('', '/** The builders: ui.Name(props, children). */', 'export interface UiBuilders {');
for (const [name, def] of Object.entries(schema.components)) {
  const kids = def.children === 'none' ? '' : ', children?: Children';
  lines.push(`  ${name}(props${(def.required ?? []).length ? '' : '?'}: ${name}Props${kids}): UiNode;`);
  if (def.children !== 'none') lines.push(`  ${name}(children: Children): UiNode;`);
}
lines.push('}', '', 'export type Children = UiNode | string | number | false | null | undefined | Children[];', '');
lines.push(`export type ComponentName = ${Object.keys(schema.components).map((n) => JSON.stringify(n)).join(' | ')};`, '');
outputs.set(path.join(pkg, 'src/components.g.d.ts'), lines.join('\n'));

let stale = 0;
for (const [file, text] of outputs) {
  const now = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (now === text) continue;
  if (check) {
    console.error(`stale: ${path.relative(root, file)} (run node packages/plugin-sdk/scripts/gen.mjs)`);
    stale++;
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, text);
    console.log(`wrote ${path.relative(root, file)}`);
  }
}
if (stale) process.exit(1);
